          <div className="chat-messages" onClick={()=>setActionMessage(null)}>{messages.map(message=>{const own=message.user_id===currentUser.id,deleted=Boolean(message.deleted_for_everyone_at);return <div key={message.id} className={`chat-bubble-row ${own?'own':''} ${deleted?'deleted':''}`}>{!own&&<Avatar user={{name:message.user_name,avatar_color:message.avatar_color}} size={29}/>}<div className="message-wrap">{!own&&<strong>{message.user_name}</strong>}<button type="button" className="message-options" aria-label="Message options" aria-expanded={actionMessage===message.id} onClick={event=>{event.stopPropagation();setActionMessage(actionMessage===message.id?null:message.id)}}><MoreHorizontal/></button><div className="message-bubble">{deleted?<p className="deleted-message"><Trash2/> This message was deleted</p>:<>{message.forwarded_from_id&&<span className="forwarded-label">↪ Forwarded</span>}{message.reply_to_id&&<div className="reply-quote"><b>{message.reply_user_name}</b><span>{message.reply_message||'Attachment'}</span></div>}{message.attachments?.length>0&&<div className="chat-attachments">{message.attachments.map(file=>file.mime_type.startsWith('image/')?<a key={file.id} href={`/api/chat/attachments/${file.id}`} target="_blank" rel="noreferrer"><img src={`/api/chat/attachments/${file.id}`} alt={file.filename}/><span>{file.filename}</span></a>:<a key={file.id} className="chat-file" href={`/api/chat/attachments/${file.id}`} download><FileText/><span><b>{file.filename}</b><small>{Math.ceil(file.file_size/1024)} KB</small></span><Download/></a>)}</div>}{message.message&&<p>{message.message}</p>}</>}<small>{new Date(message.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}{own&&!deleted&&ticks(message)}</small></div>{!deleted&&message.reactions?.length>0&&<div className="message-reactions">{message.reactions.map(reaction=><button className={reaction.reacted?'mine':''} key={reaction.emoji} onClick={event=>{event.stopPropagation();react(message,reaction.emoji)}}>{reaction.emoji} {reaction.count}</button>)}</div>}{actionMessage===message.id&&<div className="message-actions" onClick={event=>event.stopPropagation()}>{!deleted&&<><button onClick={()=>{setReplyTo(message);setActionMessage(null)}}>↩ Reply</button>{quickReactions.map(emoji=><button className="reaction-action" key={emoji} onClick={()=>react(message,emoji)}>{emoji}</button>)}<button onClick={()=>{setForwardMessage(message);setForwardTargets([]);setActionMessage(null)}}>↪ Forward</button></>}<button className="delete-action" onClick={()=>{setDeleteMessage(message);setActionMessage(null)}}><Trash2/> Delete</button></div>}</div></div>})}<div ref={messagesEnd}/></div>
          {replyTo&&<div className="composer-reply"><span><b>Replying to {replyTo.user_name}</b>{replyTo.message||'Attachment'}</span><button onClick={()=>setReplyTo(null)}><X/></button></div>}
          {files.length>0&&<div className="chat-file-preview"><Paperclip/><span>{files.map(file=>file.name).join(', ')}</span><button onClick={()=>setFiles([])}><X/></button></div>}
