  return <><section className="page-heading compact"><div><span className="eyebrow">INTERNAL COMMUNICATION</span><h1>Chat</h1><p>Real-time direct conversations, team channels, images, and documents.</p></div><button className="primary" onClick={()=>setCompose(true)}><Plus size={17}/> New conversation</button></section><div className="chat-shell"><aside className="chat-channels"><div className="chat-channel-head"><strong>Messages</strong><span>{channels.length} conversations</span></div>{channels.map(channel=><button key={channel.id} className={selectedId===channel.id?'active':''} onClick={()=>setSelectedId(channel.id)}><span className={`channel-avatar ${channel.channel_type}`}>{channel.channel_type==='team'?<Hash size={16}/>:<Avatar user={channel.members?.find(m=>m.id!==currentUser.id)} size={34}/>}</span><div><strong>{channelName(channel)}</strong><p>{channel.last_message||'Photo, document, or new conversation'}</p></div>{channel.last_message_at&&<small>{new Date(channel.last_message_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small>}</button>)}{!channels.length&&<div className="no-channels"><MessageCircle/><span>No conversations yet</span></div>}</aside><section className="chat-conversation">{selected?<><header><div className="channel-avatar team">{selected.channel_type==='team'?<Hash size={17}/>:<Avatar user={selected.members?.find(m=>m.id!==currentUser.id)} size={34}/>}</div><div><strong>{channelName(selected)}</strong><span>{selected.channel_type==='team'?`${selected.members?.length||0} team members`:'Direct message · real-time'}</span></div>{selected.channel_type==='team'&&<div className="avatars-stack">{selected.members?.slice(0,5).map(u=><Avatar key={u.id} user={u}/>)}</div>}</header><div className="chat-messages">{messages.map((message,index)=>{const own=message.user_id===currentUser.id,showName=index===0||messages[index-1].user_id!==message.user_id;return <div key={message.id} className={`chat-bubble-row ${own?'own':''}`}>{!own&&<Avatar user={{name:message.user_name,avatar_color:message.avatar_color}} size={29}/>}<div>{showName&&!own&&<strong>{message.user_name}</strong>}{message.attachments?.length>0&&<div className="chat-attachments">{message.attachments.map(file=>file.mime_type.startsWith('image/')?<a key={file.id} href={`/api/chat/attachments/${file.id}`} target="_blank"><img src={`/api/chat/attachments/${file.id}`} alt={file.filename}/><span>{file.filename}</span></a>:<a key={file.id} className="chat-file" href={`/api/chat/attachments/${file.id}`} download><FileText/><span><b>{file.filename}</b><small>{Math.ceil(file.file_size/1024)} KB</small></span><Download/></a>)}</div>}{message.message&&<p>{message.message}</p>}<small>{new Date(message.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} {own?'✓✓':''}</small></div></div>})}</div>{files.length>0&&<div className="chat-file-preview"><Paperclip/><span>{files.map(f=>f.name).join(', ')}</span><button onClick={()=>setFiles([])}><X/></button></div>}<form className="chat-compose" onSubmit={sendMessage}><div className="compose-tools"><button type="button" onClick={()=>setEmojiOpen(!emojiOpen)}>☺</button><label><Paperclip/><input type="file" multiple accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.zip" onChange={e=>setFiles([...e.target.files])}/></label>{emojiOpen&&<div className="emoji-picker">{['😀','😂','😊','👍','🙏','🎉','✅','❤️','👋','💯','🤝','📌'].map(emoji=><button type="button" key={emoji} onClick={()=>{setTextValue(v=>v+emoji);setEmojiOpen(false)}}>{emoji}</button>)}</div>}</div><textarea value={textValue} onChange={e=>setTextValue(e.target.value)} required={!files.length} placeholder={`Message ${channelName(selected)}...`}/><button className="primary" disabled={busy}><Send size={16}/></button></form></>:<Empty icon={MessageCircle} title="Choose a conversation" text="Start a direct message or open a team channel."/>}</section></div>{compose&&<NewConversation data={data} currentUser={currentUser} onClose={()=>setCompose(false)} onCreated={async channel=>{setCompose(false);await loadChannels();setSelectedId(channel.id)}}/>}</>;
