function InstantMeetingForm({data,currentUser,onClose,onSubmit}){
  const [title,setTitle]=useState('Instant team meeting'),[mode,setMode]=useState('video'),[selected,setSelected]=useState([]),[search,setSearch]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const people=data.users.filter(person=>person.id!==currentUser.id&&person.status==='active'&&`${person.name} ${person.role}`.toLowerCase().includes(search.toLowerCase()));
  const toggle=id=>setSelected(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);
  const start=async()=>{setBusy(true);setError('');try{const startAt=new Date(),endAt=new Date(startAt.getTime()+2*60*60*1000);await onSubmit({title,description:'Instant DSS Flow meeting',start_at:startAt.toISOString(),end_at:endAt.toISOString(),attendee_ids:selected,meeting_mode:mode,is_instant:true})}catch(err){setError(err.message);setBusy(false)}};
  return <Modal title="New instant meeting" subtitle="Select employees and share the internal room immediately" onClose={onClose} wide><div className="instant-meeting-form"><Field label="Meeting title" full><input autoFocus value={title} onChange={event=>setTitle(event.target.value)} placeholder="Instant team meeting"/></Field><div className="meeting-mode-picker"><button className={mode==='video'?'selected':''} onClick={()=>setMode('video')}><Video/><span><strong>Video meeting</strong><small>Camera and microphone</small></span></button><button className={mode==='voice'?'selected':''} onClick={()=>setMode('voice')}><Mic/><span><strong>Voice meeting</strong><small>Microphone only</small></span></button></div><div className="instant-people-head"><strong>Share with employees</strong><span>{selected.length} selected</span></div><div className="instant-search"><Search/><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search employees"/></div><div className="instant-people-list">{people.map(person=><button key={person.id} onClick={()=>toggle(person.id)}><Avatar user={person}/><span><strong>{person.name}</strong><small>{person.role}</small></span><i className={selected.includes(person.id)?'selected':''}>{selected.includes(person.id)?'✓':''}</i></button>)}</div><div className="instant-info"><Send/>The invitation is sent to every selected employee through DSS Flow chat and notifications.</div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><span/><div><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy||!title.trim()} onClick={start}><Video/>{busy?'Starting...':'Start and share'}</button></div></div></div></Modal>
}

function RemoteVideo({participant}){const ref=useRef(null);useEffect(()=>{if(ref.current)ref.current.srcObject=participant.stream},[participant.stream]);return <div className="video-tile"><video ref={ref} autoPlay playsInline/><span>{participant.name}</span></div>}

function MeetingRoom({meeting,user,onClose}){
  const localVideo=useRef(null),streamRef=useRef(null),peers=useRef(new Map()),names=useRef(new Map());
  const[remotes,setRemotes]=useState([]),[mic,setMic]=useState(true),[camera,setCamera]=useState(meeting.meeting_mode!=='voice'),[sharing,setSharing]=useState(false),[error,setError]=useState(''),[ready,setReady]=useState(false);
  const[panel,setPanel]=useState(null),[chatMessages,setChatMessages]=useState([]),[chatText,setChatText]=useState(''),[raised,setRaised]=useState(false),[raisedHands,setRaisedHands]=useState({}),[roomPeople,setRoomPeople]=useState([]),[seconds,setSeconds]=useState(0);
  useEffect(()=>{const timer=setInterval(()=>setSeconds(value=>value+1),1000);return()=>clearInterval(timer)},[]);
  useEffect(()=>{let active=true;const addRemote=(id,stream)=>setRemotes(current=>[...current.filter(p=>p.id!==id),{id,name:names.current.get(id)||'Participant',stream}]);const setup=async()=>{try{const config=await api('/webrtc-config'),stream=await navigator.mediaDevices.getUserMedia({video:meeting.meeting_mode!=='voice',audio:true});if(!active){stream.getTracks().forEach(t=>t.stop());return}streamRef.current=stream;if(localVideo.current)localVideo.current.srcObject=stream;setReady(true);api('/users/me/status',{method:'PATCH',body:JSON.stringify({work_status:'in_meeting'})}).catch(()=>{});const getPeer=id=>{if(peers.current.has(id))return peers.current.get(id);const pc=new RTCPeerConnection(config);stream.getTracks().forEach(track=>pc.addTrack(track,stream));pc.onicecandidate=e=>e.candidate&&realtime.emit('webrtc-ice',{target:id,candidate:e.candidate});pc.ontrack=e=>addRemote(id,e.streams[0]);pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState))setRemotes(current=>current.filter(p=>p.id!==id))};peers.current.set(id,pc);return pc};const participants=async list=>{setRoomPeople(list);for(const person of list){names.current.set(person.id,person.name);const pc=getPeer(person.id),offer=await pc.createOffer();await pc.setLocalDescription(offer);realtime.emit('webrtc-offer',{target:person.id,offer})}};const offer=async({from,offer,name})=>{names.current.set(from,name);const pc=getPeer(from);await pc.setRemoteDescription(offer);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);realtime.emit('webrtc-answer',{target:from,answer})};const answer=async({from,answer})=>{const pc=peers.current.get(from);if(pc)await pc.setRemoteDescription(answer)};const ice=async({from,candidate})=>{const pc=peers.current.get(from);if(pc)try{await pc.addIceCandidate(candidate)}catch{}};const joined=person=>setRoomPeople(current=>[...current.filter(item=>item.id!==person.id),person]);const left=({id})=>{peers.current.get(id)?.close();peers.current.delete(id);setRemotes(current=>current.filter(p=>p.id!==id));setRoomPeople(current=>current.filter(p=>p.id!==id))};const receiveChat=item=>setChatMessages(current=>[...current,item]);const receiveHand=item=>setRaisedHands(current=>({...current,[item.socketId]:item.raised?item.userName:undefined}));const joinRoom=()=>realtime.emit('join-meeting',{roomName:meeting.room_name});realtime.on('meeting-participants',participants);realtime.on('webrtc-offer',offer);realtime.on('webrtc-answer',answer);realtime.on('webrtc-ice',ice);realtime.on('participant-joined',joined);realtime.on('participant-left',left);realtime.on('meeting-chat',receiveChat);realtime.on('meeting-hand',receiveHand);realtime.on('connect',joinRoom);if(realtime.connected)joinRoom();stream._cleanup=()=>{realtime.off('meeting-participants',participants);realtime.off('webrtc-offer',offer);realtime.off('webrtc-answer',answer);realtime.off('webrtc-ice',ice);realtime.off('participant-joined',joined);realtime.off('participant-left',left);realtime.off('meeting-chat',receiveChat);realtime.off('meeting-hand',receiveHand);realtime.off('connect',joinRoom)}}catch(err){setError(err.name==='NotAllowedError'?'Camera or microphone permission was denied. Allow access in Chrome and try again.':err.message)}};setup();return()=>{active=false;realtime.emit('leave-meeting',{roomName:meeting.room_name});streamRef.current?._cleanup?.();streamRef.current?.getTracks().forEach(t=>t.stop());peers.current.forEach(pc=>pc.close());api('/users/me/status',{method:'PATCH',body:JSON.stringify({work_status:'available'})}).catch(()=>{})}},[meeting.room_name]);
  const toggleTrack=kind=>{const track=streamRef.current?.getTracks().find(t=>t.kind===kind);if(track){track.enabled=!track.enabled;kind==='audio'?setMic(track.enabled):setCamera(track.enabled)}};const share=async()=>{if(sharing)return;try{const display=await navigator.mediaDevices.getDisplayMedia({video:true}),track=display.getVideoTracks()[0];peers.current.forEach(pc=>pc.getSenders().find(s=>s.track?.kind==='video')?.replaceTrack(track));if(localVideo.current)localVideo.current.srcObject=display;setSharing(true);track.onended=()=>{const cameraTrack=streamRef.current?.getVideoTracks()[0];peers.current.forEach(pc=>pc.getSenders().find(s=>s.track?.kind==='video')?.replaceTrack(cameraTrack));if(localVideo.current)localVideo.current.srcObject=streamRef.current;setSharing(false)}}catch{}};
  const toggleHand=()=>{const value=!raised;setRaised(value);realtime.emit('meeting-hand',{roomName:meeting.room_name,raised:value})};
  const sendMeetingChat=event=>{event.preventDefault();if(!chatText.trim())return;realtime.emit('meeting-chat',{roomName:meeting.room_name,message:chatText});setChatText('')};
  const copyInvite=async()=>{const url=new URL(location.href);url.searchParams.set('meeting',meeting.room_name);await navigator.clipboard.writeText(url.toString())};
  const toggleFullscreen=()=>document.fullscreenElement?document.exitFullscreen():document.querySelector('.meeting-room-overlay')?.requestFullscreen();
  const elapsed=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
  const participants=[{id:'self',name:user.name,role:'You'},...roomPeople.map(person=>({...person,role:'Participant'}))];
  return <div className="meeting-room-overlay">
    <header><div className="meeting-room-brand"><img src="/dsslogo.31878f461bb1d61573f8.jpg"/><span><strong>{meeting.title}</strong><small>Connected · Encrypted DSS Flow meeting</small></span></div><div className="meeting-header-actions"><b>{elapsed}</b><button className="copy-invite" onClick={copyInvite}><Copy/> Copy invite link</button></div></header>
    <div className="meeting-stage"><div className={`internal-video-grid participants-${Math.min(remotes.length+1,4)}`}><div className="video-tile local"><video ref={localVideo} autoPlay muted playsInline/><span>{user.name} (You)</span>{raised&&<i className="raised-hand-badge">✋</i>}{!ready&&!error&&<div className="video-loading"><div className="loader"/><span>Starting camera and microphone...</span></div>}</div>{remotes.map(participant=><div className="remote-wrap" key={participant.id}><RemoteVideo participant={participant}/>{raisedHands[participant.id]&&<i className="raised-hand-badge">✋</i>}</div>)}{error&&<div className="meeting-error"><Video/><strong>Unable to join</strong><p>{error}</p></div>}</div>
      {panel&&<aside className="meeting-side-panel"><div className="meeting-panel-head"><strong>{panel==='chat'?'Meeting chat':'People'}</strong><button onClick={()=>setPanel(null)}><X/></button></div>{panel==='chat'?<><div className="meeting-chat-list">{chatMessages.length?chatMessages.map(item=><article key={item.id} className={item.userId===user.id?'own':''}><strong>{item.userName}</strong><p>{item.message}</p><small>{new Date(item.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></article>):<div className="meeting-panel-empty"><MessageCircle/><span>No messages yet</span></div>}</div><form className="meeting-chat-compose" onSubmit={sendMeetingChat}><input value={chatText} onChange={event=>setChatText(event.target.value)} placeholder="Message everyone"/><button><Send/></button></form></>:<div className="meeting-people-list">{participants.map(person=><article key={person.id}><Avatar user={{name:person.name,avatar_color:'#2c5de5'}}/><span><strong>{person.name}</strong><small>{person.role}</small></span>{raisedHands[person.id]&&<i>✋</i>}</article>)}</div>}</aside>}
    </div>
    <div className="meeting-footer"><div className="participant-total"><strong>{roomPeople.length+1}</strong><span>Participants</span></div><div className="meeting-controls"><button className={mic?'':'off'} onClick={()=>toggleTrack('audio')}><Mic/>{mic?'Mute':'Unmute'}</button><button disabled={meeting.meeting_mode==='voice'} className={camera?'':'off'} onClick={()=>toggleTrack('video')}><Video/>{camera?'Camera':'Start camera'}</button><button className={sharing?'active':''} onClick={share}><MonitorUp/>{sharing?'Sharing':'Share screen'}</button><button className={raised?'active':''} onClick={toggleHand}><Hand/>{raised?'Lower hand':'Raise hand'}</button><button className={panel==='chat'?'active':''} onClick={()=>setPanel(panel==='chat'?null:'chat')}><MessageCircle/>Chat</button><button className={panel==='people'?'active':''} onClick={()=>setPanel(panel==='people'?null:'people')}><UsersRound/>People</button><button onClick={toggleFullscreen}><Maximize/>Full screen</button></div><button className="meeting-leave" onClick={onClose}><PhoneCall/> Leave</button></div>
  </div>

}

function InstallHelp({onClose}){return <Modal title="Install DSS Flow" subtitle="Use DSS Flow like a native application on your computer or phone." onClose={onClose}><div className="install-help"><div className="chrome-mark">◉</div><div><strong>Install with Google Chrome</strong><ol><li>Open DSS Flow in Chrome.</li><li>Click the install icon in the address bar, or open the three-dot Chrome menu.</li><li>Select <b>Install DSS Flow</b> or <b>Add to Home screen</b>.</li><li>Confirm Install.</li></ol></div></div><div className="permission-note"><Download/><div><strong>Mobile and desktop</strong><span>The installed app has its own icon and window, while staying connected to your Neon workspace.</span></div></div><div className="modal-actions result-actions"><span/><div><button className="primary" onClick={onClose}>Got it</button></div></div></Modal>}

function TeamsWithMembers({data,setModal,canManage}) {
  return <><section className="page-heading compact"><div><span className="eyebrow">COLLABORATION</span><h1>Teams</h1><p>Bring the right people together around shared work.</p></div>{canManage&&<button className="primary" onClick={()=>setModal('team')}><Plus size={17}/> Create team</button>}</section><div className="team-grid">{data.teams.map(team=>{const members=data.users.filter(user=>team.member_ids?.includes(user.id)),active=data.tasks.filter(task=>task.team_id===team.id&&task.status!=='done').length,completed=data.tasks.filter(task=>task.team_id===team.id&&task.status==='done').length;return <article className="team-card" key={team.id}><div className="team-art" style={{background:`linear-gradient(135deg, ${team.color}25, ${team.color}08)`}}><Users style={{color:team.color}}/><span>{members.length} members</span></div><h2>{team.name}</h2><p>{team.description}</p><div className="team-stats"><span><strong>{active}</strong> active tasks</span><span><strong>{completed}</strong> completed</span></div><div className="team-foot"><div className="avatars-stack">{members.slice(0,8).map(user=><Avatar key={user.id} user={user}/>)}</div><button onClick={()=>setModal({type:'team-members',team})}>View members <ArrowUpRight size={14}/></button></div></article>})}{canManage&&<button className="new-project-card team-new" onClick={()=>setModal('team')}><span><Plus/></span><strong>Create a team</strong><p>Group people by function or project</p></button>}</div></>;
}

function TeamMembersModal({team,teams,users,canManage,onUpdated,onClose}) {
  const[memberIds,setMemberIds]=useState(team.member_ids||[]),[adding,setAdding]=useState(false),[selected,setSelected]=useState([]),[query,setQuery]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[moveTargets,setMoveTargets]=useState({}),[memberBusy,setMemberBusy]=useState(null),[memberError,setMemberError]=useState('');
  const members=users.filter(user=>memberIds.includes(user.id)),candidates=users.filter(user=>user.status==='active'&&`${user.name} ${user.email} ${user.role}`.toLowerCase().includes(query.trim().toLowerCase()));
  const toggle=id=>setSelected(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);
  const addMembers=async()=>{if(!selected.length)return;setBusy(true);setError('');try{const result=await api(`/teams/${team.id}/members`,{method:'PATCH',body:JSON.stringify({user_ids:selected})});setMemberIds(result.member_ids);setSelected([]);setQuery('');setAdding(false);await onUpdated()}catch(err){setError(err.message)}finally{setBusy(false)}};
  const manageMember=async(user,targetTeamId=null)=>{const target=teams.find(item=>item.id===Number(targetTeamId)),message=target?`Move ${user.name} from ${team.name} to ${target.name}?`:`Remove ${user.name} from ${team.name}?`;if(!window.confirm(message))return;setMemberBusy(user.id);setMemberError('');try{const result=await api(`/teams/${team.id}/members/${user.id}`,{method:'PATCH',body:JSON.stringify({target_team_id:target?.id||null})});setMemberIds(result.member_ids);setMoveTargets(current=>({...current,[user.id]:''}));await onUpdated()}catch(err){setMemberError(err.message)}finally{setMemberBusy(null)}};
  return <Modal title={team.name} subtitle={`${members.length} team member${members.length===1?'':'s'}`} onClose={onClose} wide>
    <div className="team-member-summary" style={{background:`linear-gradient(135deg,${team.color}20,${team.color}08)`}}><span style={{background:team.color}}><Users/></span><div><strong>{team.name}</strong><p>{team.description||'Workspace team'}</p></div>{canManage&&<button className="secondary team-add-trigger" onClick={()=>{setAdding(value=>!value);setError('')}}><UserPlus/> {adding?'Cancel':'Add employees'}</button>}</div>
    {adding&&<div className="team-add-panel"><div className="team-add-search"><Search/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search by name, email, or role..."/><span>{selected.length} selected</span></div><div className="team-add-list">{candidates.length?candidates.map(user=>{const alreadyMember=memberIds.includes(user.id);return <button type="button" key={user.id} disabled={alreadyMember} className={`${selected.includes(user.id)?'selected':''} ${alreadyMember?'already-member':''}`} onClick={()=>toggle(user.id)}><Avatar user={user} size={38}/><span><strong>{user.name}</strong><small>{alreadyMember?'Already in team':`${user.email} · ${user.role}`}</small></span><i>{alreadyMember||selected.includes(user.id)?'✓':'+'}</i></button>}):<div className="team-add-empty">No employees match “{query}”.</div>}</div>{error&&<div className="form-error">{error}</div>}<div className="team-add-actions"><span>{selected.length?`${selected.length} employee${selected.length===1?'':'s'} ready to add`:'Search and select employees who are not already members'}</span><button className="primary" disabled={!selected.length||busy} onClick={addMembers}>{busy?'Adding...':'Add selected'}</button></div></div>}
    {memberError&&<div className="form-error team-member-error">{memberError}</div>}
    <div className={`team-member-list ${canManage?'manageable':''}`}>{members.length?members.map(user=>{const presence=workStatuses[user.work_status]||workStatuses.offline,isBusy=memberBusy===user.id;return <article key={user.id}><Avatar user={user} size={42}/><div><strong>{user.name}</strong><span>{user.email}</span></div><span className="team-member-role">{user.role}</span><span className="team-member-presence"><i style={{background:presence.color}}/>{presence.label}{user.status_note&&<small>{user.status_note}</small>}</span>{canManage&&<div className="team-member-manage"><select aria-label={`Move ${user.name} to another team`} value={moveTargets[user.id]||''} onChange={event=>setMoveTargets(current=>({...current,[user.id]:event.target.value}))} disabled={isBusy}><option value="">Move to team...</option>{teams.filter(item=>item.id!==team.id).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button type="button" className="team-move-button" title="Move member" aria-label={`Move ${user.name}`} disabled={!moveTargets[user.id]||isBusy} onClick={()=>manageMember(user,moveTargets[user.id])}><ArrowRightLeft/></button><button type="button" className="team-remove-button" title="Remove from team" aria-label={`Remove ${user.name} from team`} disabled={isBusy} onClick={()=>manageMember(user)}><Trash2/></button></div>}</article>}):<Empty icon={Users} title="No members yet" text={canManage?'Use Add employees to build this team.':'This team has no members yet.'}/>}</div>
    <div className="modal-actions team-members-actions"><span/><div><button className="primary" onClick={onClose}>Done</button></div></div>
  </Modal>;
}

function Teams({ data, setModal, canManage }) { return <><section className="page-heading compact"><div><span className="eyebrow">COLLABORATION</span><h1>Teams</h1><p>Bring the right people together around shared work.</p></div>{canManage&&<button className="primary" onClick={()=>setModal('team')}><Plus size={17}/> Create team</button>}</section><div className="team-grid">{data.teams.map(team=>{const members=data.users.filter(u=>team.member_ids?.includes(u.id)); const count=data.tasks.filter(t=>t.team_id===team.id&&t.status!=='done').length;return <div className="team-card" key={team.id}><div className="team-art" style={{background:`linear-gradient(135deg, ${team.color}25, ${team.color}08)`}}><Users style={{color:team.color}}/><span>{members.length} members</span></div><h2>{team.name}</h2><p>{team.description}</p><div className="team-stats"><span><strong>{count}</strong> active tasks</span><span><strong>{data.tasks.filter(t=>t.team_id===team.id&&t.status==='done').length}</strong> completed</span></div><div className="team-foot"><div className="avatars-stack">{members.map(u=><Avatar key={u.id} user={u}/>)}</div><button>View team <ArrowUpRight size={14}/></button></div></div>})}{canManage&&<button className="new-project-card team-new" onClick={()=>setModal('team')}><span><Plus/></span><strong>Create a team</strong><p>Group people by function or project</p></button>}</div></> }

function People({ data, currentUser, setModal, updateUser, canManage }) {
  const[query,setQuery]=useState(''),[openMenu,setOpenMenu]=useState(null);useEffect(()=>{const close=()=>setOpenMenu(null);window.addEventListener('click',close);return()=>window.removeEventListener('click',close)},[]);const people=data.users.filter(u=>`${u.name} ${u.email} ${u.role}`.toLowerCase().includes(query.toLowerCase()));
  return <><section className="page-heading compact"><div><span className="eyebrow">DIRECTORY</span><h1>People</h1><p>Manage employee roles, access, credentials, and workspace membership.</p></div>{canManage&&<button className="primary" onClick={()=>setModal('invite')}><UserPlus size={17}/> Invite people</button>}</section><div className="people-layout"><div className="list-panel people-panel"><div className="people-tools"><div><h2>Workspace members</h2><span>{data.users.filter(u=>u.status==='active').length} active · {data.users.filter(u=>u.status==='suspended').length} suspended</span></div><div className="mini-search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a person..."/></div></div>{people.map(u=><div className={`person-row ${u.status==='suspended'?'suspended-row':''}`} key={u.id}><Avatar user={u} size={40}/><div className="person-name"><strong>{u.name}{u.id===currentUser.id&&<small> You</small>}</strong><span>{u.email}</span></div><span className="person-role">{u.role}</span><div className="person-teams">{data.teams.filter(t=>t.member_ids?.includes(u.id)).slice(0,2).map(t=><i key={t.id} style={{color:t.color,background:`${t.color}15`}}>{t.name}</i>)}</div><span className={`active-pill ${u.status==='suspended'?'suspended':''}`}><i/>{u.status==='suspended'?'Suspended':'Active'}</span>{u.id===currentUser.id?<span className="self-account">Your account</span>:<div className="person-menu-wrap"><button className="icon-btn" aria-label={`Manage ${u.name}`} onClick={e=>{e.stopPropagation();setOpenMenu(openMenu===u.id?null:u.id)}}><MoreHorizontal size={17}/></button>{openMenu===u.id&&<div className="person-menu" onClick={e=>e.stopPropagation()}><button onClick={()=>{setOpenMenu(null);setModal({type:'edit-user',user:u})}}><UserCog size={15}/><span>Change role</span></button><button onClick={()=>{setOpenMenu(null);updateUser(u.id,{status:u.status==='suspended'?'active':'suspended'})}}>{u.status==='suspended'?<ShieldCheck size={15}/>:<ShieldOff size={15}/>}<span>{u.status==='suspended'?'Restore access':'Suspend access'}</span></button><button onClick={()=>{setOpenMenu(null);setModal({type:'reset-user',user:u})}}><KeyRound size={15}/><span>Reset password</span></button><i/><button className="delete-option" onClick={()=>{setOpenMenu(null);setModal({type:'remove-user',user:u})}}><UserX size={15}/><span>Remove employee</span></button></div>}</div>}</div>)}</div>{canManage&&<aside className="invite-panel"><div className="invite-art"><Sparkles/><UserPlus/></div><h2>Grow your team</h2><p>Invite collaborators to plan projects, join teams, and deliver work together.</p><button className="primary" onClick={()=>setModal('invite')}>Invite a teammate</button>{data.invitations.length>0&&<div className="pending"><strong>Pending invitations</strong>{data.invitations.slice(0,4).map(i=><div key={i.id}><span>{i.email}</span><b>{i.status}</b></div>)}</div>}</aside>}</div></>;
}

function UserRoleForm({user,onClose,onSubmit}){const[role,setRole]=useState(user.role),[busy,setBusy]=useState(false),[error,setError]=useState('');const descriptions={Employee:'Works on assigned tasks; cannot manage projects, teams, people, or create tasks.',Member:'Collaborates on shared projects and tasks.', 'Project Manager':'Creates projects, teams, tasks, meetings, and invitations.','Workspace Admin':'Full workspace and employee account control.',Guest:'Limited access to explicitly shared work.'};return <Modal title="Change workspace role" subtitle={`Update permissions for ${user.name}.`} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSubmit({role})}catch(err){setError(err.message)}finally{setBusy(false)}}}><Field label="Workspace role" full><select value={role} onChange={e=>setRole(e.target.value)}><option>Employee</option><option>Member</option><option>Project Manager</option><option>Workspace Admin</option><option>Guest</option></select></Field><div className="role-description"><UserCog/><div><strong>{role}</strong><span>{descriptions[role]}</span></div></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><span/><div><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy||role===user.role}>{busy?'Saving...':'Update role'}</button></div></div></form></Modal>}

function ResetPasswordConfirm({user,onClose,onConfirm}){const[busy,setBusy]=useState(false),[error,setError]=useState('');return <Modal title="Reset employee password?" subtitle="This immediately signs the employee out on every device." onClose={onClose}><div className="account-action"><span><KeyRound/></span><div><strong>{user.name}</strong><p>A new temporary password will be generated and emailed to <b>{user.email}</b>. They must replace it at their next sign-in.</p></div></div>{error&&<div className="form-error action-error">{error}</div>}<div className="modal-actions result-actions"><span/><div><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await onConfirm()}catch(err){setError(err.message);setBusy(false)}}}>{busy?'Resetting...':'Reset and email password'}</button></div></div></Modal>}

function RemoveUserConfirm({user,onClose,onConfirm}){const[confirm,setConfirm]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <Modal title="Remove employee?" subtitle="This permanently removes their DSS Flow account and workspace access." onClose={onClose}><div className="account-action destructive"><span><UserX/></span><div><strong>{user.name}</strong><p>Their sessions and team memberships will be removed. Assigned tasks remain in the workspace but become unassigned.</p></div></div><div className="confirm-project-name"><label>Type <strong>{user.email}</strong> to confirm</label><input autoFocus value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder={user.email}/></div>{error&&<div className="form-error action-error">{error}</div>}<div className="modal-actions result-actions"><span/><div><button className="secondary" onClick={onClose}>Cancel</button><button className="danger-confirm" disabled={confirm!==user.email||busy} onClick={async()=>{setBusy(true);setError('');try{await onConfirm()}catch(err){setError(err.message);setBusy(false)}}}>{busy?'Removing...':'Remove employee'}</button></div></div></Modal>}

function PasswordResetResult({user,item,onClose}){const[copied,setCopied]=useState(false);return <Modal title="Temporary password created" subtitle="Zoho email delivery was unavailable, so share these credentials securely." onClose={onClose}><div className="credential-box"><Field label="Employee" full><input readOnly value={user.name}/></Field><Field label="Login email" full><input readOnly value={item.email}/></Field><Field label="Temporary password" full><input readOnly value={item.temporary_password}/></Field><button className="primary" onClick={async()=>{await navigator.clipboard.writeText(`Login: ${item.email}\nTemporary password: ${item.temporary_password}`);setCopied(true)}}>{copied?<CircleCheck size={16}/>:<FileText size={16}/>} {copied?'Copied':'Copy credentials'}</button></div><div className="modal-actions result-actions"><span/><div><button className="primary" onClick={onClose}>Done</button></div></div></Modal>}

function Empty({icon:Icon,title,text}){return <div className="empty"><Icon/><strong>{title}</strong><p>{text}</p></div>}

function TaskForm({ data, currentUser, defaultProject, task, onClose, onSubmit, onDelete, onRefresh }) {
  const [form,setForm]=useState(task||{title:'',description:'',project_id:defaultProject||data.projects[0]?.id,assignee_id:'',team_id:'',status:'todo',priority:'medium',due_date:'',completion_summary:'',completion_notes:''});
  const [files,setFiles]=useState([]); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const change=e=>setForm({...form,[e.target.name]:e.target.value});
  return <Modal title={task?'Task details':'Create a new task'} subtitle={task?'Instructions, documents, questions, and delivery details in one place.':'Describe the work clearly and attach any supporting documents.'} onClose={onClose} wide>
    <form className="task-detail-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const item=await onSubmit({...form,project_id:Number(form.project_id),assignee_id:form.assignee_id?Number(form.assignee_id):null,team_id:form.team_id?Number(form.team_id):null});const taskId=item?.id||task?.id;if(files.length&&taskId)await uploadDocuments(taskId,files);await onRefresh();onClose()}catch(err){setError(err.message)}finally{setBusy(false)}}}>
      <div className="form-grid"><Field label="Task title" full><input autoFocus={!task} required name="title" value={form.title} onChange={change} placeholder="What needs to be done?"/></Field><Field label={`Full task description and instructions${['Employee','Guest'].includes(currentUser.role)?' (read only)':''}`} full><textarea className={`description-area ${['Employee','Guest'].includes(currentUser.role)?'readonly-field':''}`} name="description" value={form.description||''} onChange={change} readOnly={['Employee','Guest'].includes(currentUser.role)} placeholder="Explain the goal, exact steps, expected result, links, requirements, and definition of done..."/></Field><Field label="Project"><select required name="project_id" value={form.project_id} onChange={change}>{data.projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Assignee"><select name="assignee_id" value={form.assignee_id||''} onChange={change}><option value="">Unassigned</option>{data.users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field><Field label="Team"><select name="team_id" value={form.team_id||''} onChange={change}><option value="">No team</option>{data.teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></Field><Field label="Due date"><input type="date" name="due_date" value={String(form.due_date||'').slice(0,10)} onChange={change}/></Field><Field label="Priority"><select name="priority" value={form.priority} onChange={change}>{Object.entries(priorityMeta).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}</select></Field><Field label="Status"><select name="status" value={form.status} onChange={change}>{Object.entries(statusMeta).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}</select></Field>
        {form.status==='done'&&<><Field label="Completion summary (required)" full><textarea required name="completion_summary" value={form.completion_summary||''} onChange={change} placeholder="Describe exactly what was completed and the result..."/></Field><Field label="Completion notes / handoff information" full><textarea name="completion_notes" value={form.completion_notes||''} onChange={change} placeholder="Mention testing, document locations, known limitations, or follow-up work..."/></Field></>}
        <Field label="Supporting documents" full><div className="file-input"><Paperclip size={17}/><input type="file" multiple onChange={e=>setFiles([...e.target.files])}/><span>{files.length?`${files.length} file${files.length>1?'s':''} selected`:'Attach up to 5 files, 8 MB each'}</span></div></Field>
      </div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions">{onDelete?<button type="button" className="danger-btn" onClick={onDelete}><Trash2 size={15}/> Delete</button>:<span/>}<div><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving...':task?'Save task':'Create task'}</button></div></div>
    </form>{task&&<TaskCollaboration task={task} currentUser={currentUser}/>} 
  </Modal>;
}

function TaskCollaboration({task,currentUser}) {
  const [activity,setActivity]=useState({messages:[],attachments:[]}); const [message,setMessage]=useState(''); const [type,setType]=useState('question'); const [busy,setBusy]=useState(false); const load=()=>api(`/tasks/${task.id}/activity`).then(setActivity);
  useEffect(()=>{load()},[task.id]);
  return <section className="task-collaboration"><div className="collab-title"><div><MessageCircle size={17}/><strong>Questions and updates</strong></div><span>Everyone on this task can reply</span></div>{activity.attachments.length>0&&<div className="document-list"><strong><Paperclip size={14}/> Documents</strong>{activity.attachments.map(file=><a key={file.id} href={`/api/attachments/${file.id}`}><FileText size={16}/><span>{file.filename}<small>{Math.ceil(file.file_size/1024)} KB · {file.uploaded_by_name}</small></span><Download size={15}/></a>)}</div>}<div className="message-list">{activity.messages.length?activity.messages.map(item=><div className="task-message" key={item.id}><Avatar user={{name:item.user_name,avatar_color:item.avatar_color}} size={30}/><div><p><strong>{item.user_name}</strong><i className={item.message_type}>{item.message_type}</i><small>{new Date(item.created_at).toLocaleString()}</small></p><span>{item.message}</span></div></div>):<p className="no-messages">No questions or updates yet.</p>}</div><form className="message-compose" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api(`/tasks/${task.id}/messages`,{method:'POST',body:JSON.stringify({message,message_type:type})});setMessage('');await load()}finally{setBusy(false)}}}><select value={type} onChange={e=>setType(e.target.value)}><option value="question">Ask a question</option><option value="update">Work update</option><option value="reply">Reply</option></select><textarea value={message} onChange={e=>setMessage(e.target.value)} required placeholder="Write details about your question, doubt, or progress update..."/><button className="primary" disabled={busy}><Send size={15}/>{busy?'Sending...':'Send'}</button></form></section>;
}

function ProjectForm({project,onClose,onSubmit}){const[form,setForm]=useState(project?{name:project.name,description:project.description||'',color:project.color||'#24c8d8',due_date:String(project.due_date||'').slice(0,10)}:{name:'',description:'',color:'#24c8d8',due_date:''});const[busy,setBusy]=useState(false);const[error,setError]=useState('');return <Modal title={project?'Edit project':'Create a project'} subtitle={project?'Update the project information shown to your team.':'Give your team a shared place to organize and deliver work.'} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSubmit(form)}catch(err){setError(err.message)}finally{setBusy(false)}}}><div className="form-grid"><Field label="Project name" full><input autoFocus required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="e.g. Website redesign"/></Field><Field label="Description" full><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="What is this project about?"/></Field><Field label="Accent color"><input type="color" value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></Field><Field label="Target date"><input type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></Field></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><span/><div><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving...':project?'Save changes':'Create project'}</button></div></div></form></Modal>}

function DeleteProjectConfirm({project,taskCount,onClose,onConfirm}){const[confirm,setConfirm]=useState('');const[busy,setBusy]=useState(false);return <Modal title="Delete project?" subtitle="This action permanently removes the project and everything stored inside it." onClose={onClose}><div className="delete-project-warning"><span><Trash2 size={22}/></span><div><strong>{project.name}</strong><p>This will delete {taskCount} task{taskCount===1?'':'s'}, including their messages, attached documents, completion notes, and notifications.</p></div></div><div className="confirm-project-name"><label>Type <strong>{project.name}</strong> to confirm</label><input autoFocus value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder={project.name}/></div><div className="modal-actions result-actions"><span/><div><button className="secondary" onClick={onClose}>Cancel</button><button className="danger-confirm" disabled={confirm!==project.name||busy} onClick={async()=>{setBusy(true);try{await onConfirm()}finally{setBusy(false)}}}>{busy?'Deleting...':'Delete project'}</button></div></div></Modal>}
function TeamForm({users,onClose,onSubmit}){const[form,setForm]=useState({name:'',description:'',color:'#8b7cf6',member_ids:[]}),[memberSearch,setMemberSearch]=useState('');const query=memberSearch.trim().toLowerCase(),filteredUsers=users.filter(user=>`${user.name||''} ${user.email||''} ${user.role||''}`.toLowerCase().includes(query));const toggle=id=>setForm(current=>({...current,member_ids:current.member_ids.includes(id)?current.member_ids.filter(item=>item!==id):[...current.member_ids,id]}));return <Modal title="Create a team" subtitle="Group people so work can be assigned and tracked together." onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSubmit(form)}}><div className="form-grid"><Field label="Team name" full><input autoFocus required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="e.g. Platform engineering"/></Field><Field label="Description" full><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="What does this team own?"/></Field><Field label="Team color" full><input type="color" value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></Field><Field label="Add members" full><div className="member-picker-search"><Search size={16}/><input type="search" value={memberSearch} onChange={e=>setMemberSearch(e.target.value)} placeholder="Search by name, email, or role..." aria-label="Search team members"/><span>{form.member_ids.length} selected</span></div><div className="member-picker">{filteredUsers.length?filteredUsers.map(u=><button type="button" key={u.id} className={form.member_ids.includes(u.id)?'selected':''} onClick={()=>toggle(u.id)}><Avatar user={u}/><span>{u.name}</span><i>{form.member_ids.includes(u.id)?'✓':'+'}</i></button>):<div className="member-picker-empty">No members match “{memberSearch}”.</div>}</div></Field></div><FormActions onClose={onClose} label="Create team"/></form></Modal>}
function InviteForm({onClose,onSubmit}){const[form,setForm]=useState({name:'',email:'',role:'Employee'});const[busy,setBusy]=useState(false);const[error,setError]=useState('');return <Modal title="Invite people" subtitle="We’ll create their login and send a temporary password by email." onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSubmit(form)}catch(err){setError(err.message)}finally{setBusy(false)}}}><div className="form-grid"><Field label="Employee name" full><input autoFocus required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Full name"/></Field><Field label="Work email" full><input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="name@company.com"/></Field><Field label="Workspace role" full><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option>Employee</option><option>Member</option><option>Project Manager</option><option>Workspace Admin</option><option>Guest</option></select></Field></div><div className="permission-note"><UserPlus size={18}/><div><strong>{form.role}</strong><span>{form.role==='Guest'?'Can only access projects shared with them.':form.role==='Employee'?'Can work on assigned tasks but cannot create projects, teams, or invite people.':'Can create and update tasks in shared projects.'}</span></div></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><span/><div><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Creating account...':'Send invitation'}</button></div></div></form></Modal>}
function FormActions({onClose,label}){return <div className="modal-actions"><span/><div><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary">{label}</button></div></div>}

export default App;
